import math

def f(x):
    return math.sin(x)

a, b = 0.0, math.pi
TRUE_VALUE = 2.0

def trapezoidal(n):
    h = (b - a) / n
    s = f(a) + f(b)
    for i in range(1, n):
        s = s + 2 * f(a + i * h)
    return h / 2 * s

def simpson(n):
    assert n % 2 == 0
    h = (b - a) / n
    s = f(a) + f(b)
    for i in range(1, n, 2):
        s = s + 4 * f(a + i * h)
    for i in range(2, n, 2):
        s = s + 2 * f(a + i * h)
    return h / 3 * s

for n in [4, 8, 16, 32]:
    t = trapezoidal(n)
    s = simpson(n if n % 2 == 0 else n + 1)
    print(f"n={n:3d}  trap err={abs(t-TRUE_VALUE):.2e}  simp err={abs(s-TRUE_VALUE):.2e}")

